<template><view class='page'><AppNavBar title='用户主页' show-back/><view class='container'><view class='card'><view class='avatar'>🎸</view><view class='name'>{{profile?.user.nickname||'谱友'}}</view><view class='stats'><view>{{profile?.stats.works_count||0}}作品</view><view>{{profile?.stats.followers_count||0}}粉丝</view><view>{{profile?.stats.likes_count||0}}获赞</view></view></view><SongCard v-for='song in songs' :song='song' :key='song.id'/></view></view></template><script setup lang='ts'>import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import AppNavBar from '../../components/AppNavBar.vue';import SongCard from '../../components/SongCard.vue';import {getUserProfile,getUserSongs} from '../../api/social';const profile=ref();const songs=ref([]);onLoad(async(q)=>{const id=Number(q.id);profile.value=await getUserProfile(id);songs.value=(await getUserSongs(id)).items})</script>